import React, { useState, useEffect } from "react";

export default function PasswordUuidGenerator({ isDarkMode, currentRoute }) {
  const [toolMode, setToolMode] = useState("password"); // 'password' or 'uuid'
  const [copySuccess, setCopySuccess] = useState(false);

  // Sync state with active route for SEO deep links
  useEffect(() => {
    if (!currentRoute) return;
    if (currentRoute.includes("uuid")) setToolMode("uuid");
    else if (currentRoute.includes("password")) setToolMode("password");
  }, [currentRoute]);


  // Password Generator States
  const [length, setLength] = useState(16);
  const [includeUpper, setIncludeUpper] = useState(true);
  const [includeLower, setIncludeLower] = useState(true);
  const [includeNumbers, setIncludeNumbers] = useState(true);
  const [includeSymbols, setIncludeSymbols] = useState(true);
  const [password, setPassword] = useState("");
  const [strength, setStrength] = useState("");

  // UUID Generator States
  const [uuidCount, setUuidCount] = useState(5);
  const [uuids, setUuids] = useState([]);

  useEffect(() => {
    if (toolMode === "password") {
      generatePassword();
    } else {
      generateUuids();
    }
  }, [toolMode, length, includeUpper, includeLower, includeNumbers, includeSymbols, uuidCount]);

  const generatePassword = () => {
    let charset = "";
    if (includeUpper) charset += "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    if (includeLower) charset += "abcdefghijklmnopqrstuvwxyz";
    if (includeNumbers) charset += "0123456789";
    if (includeSymbols) charset += "!@#$%^&*()_+-=[]{}|;:,.<>?";

    if (!charset) {
      setPassword("");
      setStrength("None");
      return;
    }

    let result = "";
    const randomArray = new Uint32Array(length);
    window.crypto.getRandomValues(randomArray);
    for (let i = 0; i < length; i++) {
      result += charset[randomArray[i] % charset.length];
    }
    setPassword(result);

    // Simple strength evaluator
    let strengthScore = 0;
    if (length >= 8) strengthScore++;
    if (length >= 14) strengthScore++;
    if (includeUpper) strengthScore++;
    if (includeLower) strengthScore++;
    if (includeNumbers) strengthScore++;
    if (includeSymbols) strengthScore++;

    if (strengthScore <= 2) setStrength("Weak");
    else if (strengthScore <= 4) setStrength("Medium");
    else if (strengthScore <= 5) setStrength("Strong");
    else setStrength("Very Strong");
  };

  const generateUuids = () => {
    const newUuids = [];
    const count = Math.min(Math.max(1, uuidCount), 100);
    for (let i = 0; i < count; i++) {
      newUuids.push(crypto.randomUUID());
    }
    setUuids(newUuids);
  };

  const handleCopy = (text) => {
    if (!text) return;
    navigator.clipboard.writeText(text).then(() => {
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    });
  };

  const getStrengthBadgeClass = () => {
    switch (strength) {
      case "Weak": return "bg-danger";
      case "Medium": return "bg-warning text-dark";
      case "Strong": return "bg-success";
      case "Very Strong": return "bg-success px-3 shadow-sm";
      default: return "bg-secondary";
    }
  };

  return (
    <div className="container-fluid py-4 animate-fade-in">
      {/* Header */}
      <div className="d-flex justify-content-between align-items-center mb-4">
        <div>
          <h2 className="fw-bold mb-1 d-flex align-items-center">
            <span className="badge bg-primary me-2 px-3 py-2 rounded-3 fs-6">GEN</span>
            Secure Generator Suite
          </h2>
          <p className="text-muted mb-0">Generate secure, cryptographically random passwords or batch generate UUID v4 values client-side.</p>
        </div>
        <button 
          className="btn btn-outline-secondary btn-sm shadow-sm"
          onClick={toolMode === "password" ? generatePassword : generateUuids}
        >
          <i className="fas fa-sync me-1"></i> Regenerate
        </button>
      </div>

      {/* Switcher tabs */}
      <div className="row mb-4">
        <div className="col-12">
          <div className="btn-group shadow-sm" role="group">
            <button 
              type="button" 
              className={`btn px-4 fw-semibold ${toolMode === "password" ? "btn-primary" : "btn-outline-secondary"}`}
              onClick={() => setToolMode("password")}
            >
              Password Generator
            </button>
            <button 
              type="button" 
              className={`btn px-4 fw-semibold ${toolMode === "uuid" ? "btn-primary" : "btn-outline-secondary"}`}
              onClick={() => setToolMode("uuid")}
            >
              UUID v4 Generator
            </button>
          </div>
        </div>
      </div>

      {/* Main Sandbox Grid */}
      <div className="row g-4">
        {toolMode === "password" ? (
          <>
            {/* Password Configuration */}
            <div className="col-12 col-lg-5">
              <div className={`card h-100 shadow-sm border-0 ${isDarkMode ? "bg-dark text-light" : "bg-white"}`} style={{
                background: isDarkMode ? "rgba(33, 37, 41, 0.95)" : "rgba(255, 255, 255, 0.95)",
                border: isDarkMode ? "1px solid rgba(255, 255, 255, 0.08)" : "1px solid rgba(0, 0, 0, 0.08)",
                borderRadius: "16px"
              }}>
                <div className="card-body p-4">
                  <h5 className="fw-bold mb-4">Parameters</h5>
                  
                  {/* Length range */}
                  <div className="mb-4">
                    <div className="d-flex justify-content-between align-items-center mb-2">
                      <span className="fw-medium">Length</span>
                      <span className="badge bg-secondary font-monospace fs-6">{length}</span>
                    </div>
                    <input 
                      type="range" 
                      className="form-range" 
                      min="8" 
                      max="64" 
                      value={length}
                      onChange={(e) => setLength(parseInt(e.target.value))}
                    />
                  </div>

                  {/* Character Options checkboxes */}
                  <div className="d-flex flex-column gap-3">
                    <div className="form-check form-switch">
                      <input className="form-check-input" type="checkbox" id="upperCheck" checked={includeUpper} onChange={(e) => setIncludeUpper(e.target.checked)} />
                      <label className="form-check-label fw-medium" htmlFor="upperCheck">Uppercase letters (A-Z)</label>
                    </div>
                    <div className="form-check form-switch">
                      <input className="form-check-input" type="checkbox" id="lowerCheck" checked={includeLower} onChange={(e) => setIncludeLower(e.target.checked)} />
                      <label className="form-check-label fw-medium" htmlFor="lowerCheck">Lowercase letters (a-z)</label>
                    </div>
                    <div className="form-check form-switch">
                      <input className="form-check-input" type="checkbox" id="numberCheck" checked={includeNumbers} onChange={(e) => setIncludeNumbers(e.target.checked)} />
                      <label className="form-check-label fw-medium" htmlFor="numberCheck">Numbers (0-9)</label>
                    </div>
                    <div className="form-check form-switch">
                      <input className="form-check-input" type="checkbox" id="symbolCheck" checked={includeSymbols} onChange={(e) => setIncludeSymbols(e.target.checked)} />
                      <label className="form-check-label fw-medium" htmlFor="symbolCheck">Special Symbols (!@#$)</label>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Password Result Output */}
            <div className="col-12 col-lg-7">
              <div className={`card h-100 shadow-sm border-0 ${isDarkMode ? "bg-dark text-light" : "bg-white"}`} style={{
                background: isDarkMode ? "rgba(33, 37, 41, 0.95)" : "rgba(255, 255, 255, 0.95)",
                border: isDarkMode ? "1px solid rgba(255, 255, 255, 0.08)" : "1px solid rgba(0, 0, 0, 0.08)",
                borderRadius: "16px"
              }}>
                <div className="card-body p-4 d-flex flex-column justify-content-between">
                  <div>
                    <h5 className="fw-bold mb-4">Generated Secret</h5>
                    
                    {password ? (
                      <div 
                        className={`p-3 font-monospace rounded-3 text-center border text-break mb-3 select-all ${
                          isDarkMode ? "bg-black border-secondary text-info" : "bg-light border-light text-dark"
                        }`} 
                        style={{ fontSize: "20px", cursor: "pointer", letterSpacing: "1px" }}
                        onClick={() => handleCopy(password)}
                      >
                        {password}
                      </div>
                    ) : (
                      <div className="alert alert-warning text-center">Please select at least one character set parameter.</div>
                    )}

                    {password && (
                      <div className="d-flex justify-content-between align-items-center mb-3">
                        <span className="text-muted small">Strength Rating:</span>
                        <span className={`badge ${getStrengthBadgeClass()} px-2 py-1 small fw-bold`}>{strength}</span>
                      </div>
                    )}
                  </div>

                  <div className="d-flex gap-2">
                    <button 
                      className={`btn w-100 py-2.5 fw-semibold transition-all ${
                        copySuccess ? "btn-success" : "btn-primary"
                      }`}
                      onClick={() => handleCopy(password)}
                      disabled={!password}
                    >
                      <i className={`fas ${copySuccess ? "fa-check" : "fa-copy"} me-1`}></i>
                      {copySuccess ? "Copied!" : "Copy to Clipboard"}
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </>
        ) : (
          <>
            {/* UUID Count Slider */}
            <div className="col-12 col-lg-4">
              <div className={`card h-100 shadow-sm border-0 ${isDarkMode ? "bg-dark text-light" : "bg-white"}`} style={{
                background: isDarkMode ? "rgba(33, 37, 41, 0.95)" : "rgba(255, 255, 255, 0.95)",
                border: isDarkMode ? "1px solid rgba(255, 255, 255, 0.08)" : "1px solid rgba(0, 0, 0, 0.08)",
                borderRadius: "16px"
              }}>
                <div className="card-body p-4">
                  <h5 className="fw-bold mb-4">Configuration</h5>
                  <div className="mb-4">
                    <div className="d-flex justify-content-between align-items-center mb-2">
                      <span className="fw-medium">Quantity to Generate</span>
                      <span className="badge bg-secondary font-monospace fs-6">{uuidCount}</span>
                    </div>
                    <input 
                      type="range" 
                      className="form-range" 
                      min="1" 
                      max="20" 
                      value={uuidCount}
                      onChange={(e) => setUuidCount(parseInt(e.target.value))}
                    />
                  </div>
                </div>
              </div>
            </div>

            {/* UUID Results Output */}
            <div className="col-12 col-lg-8">
              <div className={`card h-100 shadow-sm border-0 ${isDarkMode ? "bg-dark text-light" : "bg-white"}`} style={{
                background: isDarkMode ? "rgba(33, 37, 41, 0.95)" : "rgba(255, 255, 255, 0.95)",
                border: isDarkMode ? "1px solid rgba(255, 255, 255, 0.08)" : "1px solid rgba(0, 0, 0, 0.08)",
                borderRadius: "16px"
              }}>
                <div className="card-body p-4">
                  <div className="d-flex justify-content-between align-items-center mb-4">
                    <h5 className="fw-bold m-0">UUID v4 Batches</h5>
                    {uuids.length > 0 && (
                      <button 
                        className={`btn btn-sm rounded-pill px-3 py-1 fw-semibold transition-all ${
                          copySuccess ? "btn-success" : isDarkMode ? "btn-outline-light" : "btn-outline-dark"
                        }`}
                        onClick={() => handleCopy(uuids.join("\n"))}
                      >
                        <i className={`fas ${copySuccess ? "fa-check" : "fa-copy"} me-1`}></i>
                        Copy All
                      </button>
                    )}
                  </div>

                  <div className="font-monospace" style={{ maxHeight: "250px", overflowY: "auto" }}>
                    {uuids.map((id, idx) => (
                      <div 
                        key={idx} 
                        className={`p-2 px-3 mb-2 rounded-3 border text-break d-flex justify-content-between align-items-center ${
                          isDarkMode ? "bg-black border-secondary text-success" : "bg-light border-light text-dark"
                        }`}
                        style={{ fontSize: "13px" }}
                      >
                        <span>{id}</span>
                        <button className="btn btn-link btn-sm text-decoration-none p-0 text-muted" onClick={() => handleCopy(id)}>
                          <i className="fas fa-copy"></i>
                        </button>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
}
