import React, { useState, useEffect } from "react";

export default function ComplexityAnalyzer({ isDarkMode }) {
  const [code, setCode] = useState("");
  const [metrics, setMetrics] = useState({
    loc: 0,
    comments: 0,
    blankLines: 0,
    conditionals: 0,
    loops: 0,
    score: 0,
    rating: "Clean"
  });

  useEffect(() => {
    analyzeCode();
  }, [code]);

  const analyzeCode = () => {
    if (!code.trim()) {
      setMetrics({ loc: 0, comments: 0, blankLines: 0, conditionals: 0, loops: 0, score: 0, rating: "Clean" });
      return;
    }

    try {
      const lines = code.split("\n");
      const totalLoc = lines.length;
      let commentLines = 0;
      let blankLines = 0;
      let conditionalsCount = 0;
      let loopsCount = 0;

      lines.forEach((line) => {
        const trimmed = line.trim();
        if (!trimmed) {
          blankLines++;
          return;
        }

        // Standard comment checking (JS/Java/C++, Python/Ruby, HTML/XML)
        if (
          trimmed.startsWith("//") || 
          trimmed.startsWith("/*") || 
          trimmed.startsWith("*") || 
          trimmed.startsWith("#") || 
          trimmed.startsWith("<!--")
        ) {
          commentLines++;
        }

        // Count conditionals
        const conditionalMatches = trimmed.match(/\b(if|else\s+if|switch|case|catch)\b/g);
        if (conditionalMatches) conditionalsCount += conditionalMatches.length;

        // Count inline ternary / logical joins
        const inlineMatches = trimmed.match(/(\?\s*[^:]+\s*:|&&|\|\|)/g);
        if (inlineMatches) conditionalsCount += inlineMatches.length;

        // Count loops
        const loopMatches = trimmed.match(/\b(for|while|do|foreach|map|forEach)\b/g);
        if (loopMatches) loopsCount += loopMatches.length;
      });

      // Calculate Complexity score
      const complexityScore = (conditionalsCount * 2) + (loopsCount * 3) + Math.max(0, Math.floor((totalLoc - commentLines) / 15));

      let compRating = "Simple";
      if (complexityScore > 15) compRating = "Highly Complex";
      else if (complexityScore > 8) compRating = "Moderate Complexity";

      setMetrics({
        loc: totalLoc,
        comments: commentLines,
        blankLines: blankLines,
        conditionals: conditionalsCount,
        loops: loopsCount,
        score: complexityScore,
        rating: compRating
      });
    } catch (e) {
      // Ignore evaluation errors
    }
  };

  const loadSample = () => {
    const sample = `function evaluateOrder(order) {
  // Check if order details exist
  if (!order || !order.items) {
    return { status: "error", code: 400 };
  }

  let total = 0;
  // Calculate total price with loops
  for (let i = 0; i < order.items.length; i++) {
    const item = order.items[i];
    if (item.active && item.price > 0) {
      total += item.price * (item.quantity || 1);
    }
  }

  // Calculate discount tiers based on totals
  if (total > 500) {
    total = total * 0.9; // 10% off
  } else if (total > 200) {
    total = total * 0.95; // 5% off
  }

  return {
    status: "success",
    total: total,
    eligibleForShipping: total > 50 ? true : false
  };
}`;
    setCode(sample);
  };

  const getRatingBadgeClass = () => {
    switch (metrics.rating) {
      case "Highly Complex": return "bg-danger";
      case "Moderate Complexity": return "bg-warning text-dark";
      case "Simple": return "bg-success";
      default: return "bg-secondary";
    }
  };

  return (
    <div className="container-fluid py-4 animate-fade-in">
      {/* Header */}
      <div className="d-flex justify-content-between align-items-center mb-4">
        <div>
          <h2 className="fw-bold mb-1 d-flex align-items-center">
            <span className="badge bg-danger me-2 px-3 py-2 rounded-3 fs-6">ANALYZE</span>
            Code Complexity Analyzer
          </h2>
          <p className="text-muted mb-0">Evaluate cognitive complexity score levels, loops density, comments density ratios, and branch weights client-side.</p>
        </div>
        <button className="btn btn-outline-secondary btn-sm shadow-sm" onClick={loadSample}>
          <i className="fas fa-magic me-1"></i> Load JS Sample
        </button>
      </div>

      <div className="row g-4">
        {/* Code Input */}
        <div className="col-12 col-lg-6">
          <div className={`card h-100 shadow-sm border-0 ${isDarkMode ? "bg-dark text-light" : "bg-white"}`} style={{
            background: isDarkMode ? "rgba(33, 37, 41, 0.95)" : "rgba(255, 255, 255, 0.95)",
            border: isDarkMode ? "1px solid rgba(255, 255, 255, 0.08)" : "1px solid rgba(0, 0, 0, 0.08)",
            borderRadius: "16px"
          }}>
            <div className="card-header bg-transparent border-0 d-flex justify-content-between align-items-center pt-3 px-3">
              <span className="fw-bold text-uppercase tracking-wider small opacity-75">Code Input Workspace</span>
              {code && (
                <button className="btn btn-link btn-sm text-decoration-none text-danger p-0" onClick={() => setCode("")}>
                  <i className="fas fa-trash-alt me-1"></i> Clear
                </button>
              )}
            </div>
            <div className="card-body px-3 pb-3 pt-0">
              <textarea
                className={`form-control border-0 p-3 font-monospace ${isDarkMode ? "bg-dark text-info" : "bg-light text-dark"}`}
                style={{
                  height: "420px",
                  resize: "none",
                  fontSize: "13px",
                  borderRadius: "12px",
                  lineHeight: "1.6",
                  border: isDarkMode ? "1px solid rgba(255,255,255,0.05)" : "1px solid rgba(0,0,0,0.05)",
                  outline: "none"
                }}
                placeholder="Paste your function or code script block to run structural calculations..."
                value={code}
                onChange={(e) => setCode(e.target.value)}
              />
            </div>
          </div>
        </div>

        {/* Analytics Dashboard */}
        <div className="col-12 col-lg-6">
          <div className={`card h-100 shadow-sm border-0 ${isDarkMode ? "bg-dark text-light" : "bg-white"}`} style={{
            background: isDarkMode ? "rgba(33, 37, 41, 0.95)" : "rgba(255, 255, 255, 0.95)",
            border: isDarkMode ? "1px solid rgba(255, 255, 255, 0.08)" : "1px solid rgba(0, 0, 0, 0.08)",
            borderRadius: "16px"
          }}>
            <div className="card-body p-4">
              <h5 className="fw-bold mb-4">Complexity Metrics Dashboard</h5>

              <div className="row g-3 mb-4">
                {/* Score */}
                <div className="col-6">
                  <div className={`p-3 rounded-3 text-center border ${isDarkMode ? "bg-black border-secondary" : "bg-light border-light"}`}>
                    <h2 className="fw-bold m-0 text-primary">{metrics.score}</h2>
                    <span className="small text-muted text-uppercase tracking-wider">Complexity Score</span>
                  </div>
                </div>
                {/* Rating */}
                <div className="col-6">
                  <div className={`p-3 rounded-3 text-center border h-100 d-flex flex-column justify-content-center align-items-center ${isDarkMode ? "bg-black border-secondary" : "bg-light border-light"}`}>
                    <span className={`badge ${getRatingBadgeClass()} px-3 py-2 fs-6 rounded-pill fw-bold`}>{metrics.rating}</span>
                    <span className="small text-muted text-uppercase tracking-wider mt-2 d-block">Score Category</span>
                  </div>
                </div>
              </div>

              {/* Progress Bar Ratios */}
              <div className="d-flex flex-column gap-3">
                {/* LOC */}
                <div>
                  <div className="d-flex justify-content-between align-items-center small mb-1 fw-semibold">
                    <span>Lines of Code (LOC)</span>
                    <span>{metrics.loc}</span>
                  </div>
                  <div className="progress" style={{ height: "8px" }}>
                    <div className="progress-bar bg-primary" role="progressbar" style={{ width: `${Math.min(100, (metrics.loc / 100) * 100)}%` }} />
                  </div>
                </div>

                {/* Conditionals */}
                <div>
                  <div className="d-flex justify-content-between align-items-center small mb-1 fw-semibold">
                    <span>Conditionals / Logical Branches</span>
                    <span>{metrics.conditionals}</span>
                  </div>
                  <div className="progress" style={{ height: "8px" }}>
                    <div className="progress-bar bg-warning" role="progressbar" style={{ width: `${Math.min(100, (metrics.conditionals / 15) * 100)}%` }} />
                  </div>
                </div>

                {/* Loops */}
                <div>
                  <div className="d-flex justify-content-between align-items-center small mb-1 fw-semibold">
                    <span>Loop Statements</span>
                    <span>{metrics.loops}</span>
                  </div>
                  <div className="progress" style={{ height: "8px" }}>
                    <div className="progress-bar bg-danger" role="progressbar" style={{ width: `${Math.min(100, (metrics.loops / 8) * 100)}%` }} />
                  </div>
                </div>

                {/* Comments Density */}
                <div>
                  <div className="d-flex justify-content-between align-items-center small mb-1 fw-semibold">
                    <span>Comment Lines</span>
                    <span>{metrics.comments}</span>
                  </div>
                  <div className="progress" style={{ height: "8px" }}>
                    <div className="progress-bar bg-success" role="progressbar" style={{ width: `${metrics.loc ? (metrics.comments / metrics.loc) * 100 : 0}%` }} />
                  </div>
                </div>
              </div>

              <div className="mt-4 border-top pt-3 text-muted small">
                <i className="fas fa-info-circle me-1"></i> Cognitive complexity calculations evaluate conditional splits, inline logical operators, loop nesting, and relative instruction volumes.
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
