import React, { useState, useEffect } from "react";

export default function Header({ search, setSearch, isDarkMode, toggleDarkMode }) {
  return (
    <nav className={`navbar navbar-expand-lg ${isDarkMode ? "navbar-dark bg-dark" : "navbar-light bg-white"} shadow-sm px-3 d-flex align-items-center justify-content-between`}>
      <img 
        src={isDarkMode ? "/logo-dark.png" : "/logo-light.png"} 
        alt="Dev Suite Logo" 
        className="img-fluid" 
        style={{ maxHeight: "60px" }} 
      />
      <input
        type="text"
        placeholder="Search tools..."
        className={`form-control w-50 mx-3 ${isDarkMode ? "bg-dark text-light placeholder-light" : "bg-light text-dark placeholder-dark"} `}
        value={search}
        onChange={(e) => setSearch(e.target.value)}
      />
      <button
        className={`btn ${isDarkMode ? "bg-dark border-light text-light" : "bg-light border-dark text-dark"}`}
        onClick={toggleDarkMode}
      >
        {isDarkMode ? "☀ Light Mode" : "🌙 Dark Mode"}
      </button>

      <button
        className={`btn ${isDarkMode ? "bg-dark border-light text-light" : "bg-light border-dark text-dark"}`}
      >
        <i className="fa fa-coffee"></i>
        &nbsp;
        Buy Me a Coffee
      </button>
    </nav>
  );
}