import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import Header from "./components/Header";
import MainContent from "./components/MainContent";

function App() {
  const [isDarkMode, setIsDarkMode] = useState(() => {
    return localStorage.getItem("theme") === "dark";
  });

  const [currentRoute, setCurrentRoute] = useState(window.location.pathname || "/");

  useEffect(() => {
    document.body.className = isDarkMode ? "bg-dark text-light" : "bg-light text-dark";
    localStorage.setItem("theme", isDarkMode ? "dark" : "light");
  }, [isDarkMode]);

  // Standard History Routing & Popstate Listener
  useEffect(() => {
    const handlePopState = () => {
      setCurrentRoute(window.location.pathname || "/");
    };
    window.addEventListener("popstate", handlePopState);
    return () => {
      window.removeEventListener("popstate", handlePopState);
    };
  }, []);

  // Global Anchor Click Interceptor for Clean SPA Routing
  useEffect(() => {
    const handleGlobalClick = (e) => {
      const anchor = e.target.closest("a");
      if (
        anchor &&
        anchor.href &&
        anchor.host === window.location.host &&
        !anchor.getAttribute("download") &&
        anchor.getAttribute("target") !== "_blank"
      ) {
        e.preventDefault();
        const path = anchor.pathname;
        window.history.pushState(null, "", path);
        setCurrentRoute(path);
      };
    };
    document.addEventListener("click", handleGlobalClick);
    return () => {
      document.removeEventListener("click", handleGlobalClick);
    };
  }, []);


  const [isLoading, setIsLoading] = useState(false);

  // Trigger 300ms loading effect on route changes for premium app boot feeling
  useEffect(() => {
    setIsLoading(true);
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 300);
    return () => clearTimeout(timer);
  }, [currentRoute]);

  const [search, setSearch] = useState("");
  return (
    <div>
      {isLoading && (
        <div className={`loader-overlay animate-fade-in ${isDarkMode ? "" : "bg-light-theme"}`}>
          <div className="d-flex flex-column align-items-center gap-3">
            <div className="premium-spinner"></div>
            <span 
              className={`fw-semibold text-uppercase tracking-wider small ${isDarkMode ? "text-light opacity-75" : "text-dark opacity-75"}`} 
              style={{ letterSpacing: "1.5px", fontSize: "11px" }}
            >
              Loading Workspace...
            </span>
          </div>
        </div>
      )}
      <Header search={search} setSearch={setSearch} isDarkMode={isDarkMode} toggleDarkMode={() => setIsDarkMode(!isDarkMode)} />
      <MainContent search={search} setSearch={setSearch} isDarkMode={isDarkMode} currentRoute={currentRoute} />
    </div>
  );

}

export default App;

