import React, { useState, useEffect } from "react";
import JsonBeautifier from "./tools/JsonBeautifier";
import Base64EncoderDecoder from "./tools/Base64EncoderDecoder";
import UrlEncoderDecoder from "./tools/UrlEncoderDecoder";
import JwtDecoder from "./tools/JwtDecoder";
import HashGenerator from "./tools/HashGenerator";
import RegexTester from "./tools/RegexTester";
import PasswordUuidGenerator from "./tools/PasswordUuidGenerator";
import FormattersConverters from "./tools/FormattersConverters";
import OpenApiValidator from "./tools/OpenApiValidator";
import MarkdownEditor from "./tools/MarkdownEditor";
import ColorPaletteContrast from "./tools/ColorPaletteContrast";
import CronParser from "./tools/CronParser";
import NumberBaseConverter from "./tools/NumberBaseConverter";
import ComplexityAnalyzer from "./tools/ComplexityAnalyzer";

export default function MainContent({ search, setSearch, isDarkMode, currentRoute }) {
  const [tools, setTools] = useState([]);
  const [categories, setCategories] = useState([]);

  useEffect(() => {
    fetch("/data.json")
      .then(response => response.json())
      .then(data => {
        setTools(data.tools);
        setCategories(data.categories || []);
      })
      .catch(error => console.error("Error loading tools:", error));
  }, []);

  // Dynamic SEO Title & Meta Description Manager
  useEffect(() => {
    if (!tools || tools.length === 0) return;
    const matchedTool = tools.find(t => t.url === currentRoute);
    if (matchedTool) {
      document.title = `${matchedTool.title} - React Dev Suite`;
      let metaDesc = document.querySelector('meta[name="description"]');
      if (!metaDesc) {
        metaDesc = document.createElement('meta');
        metaDesc.name = "description";
        document.head.appendChild(metaDesc);
      }
      metaDesc.setAttribute("content", matchedTool.description);
    } else {
      document.title = "React Dev Suite - Developer Utilities Directory";
      let metaDesc = document.querySelector('meta[name="description"]');
      if (metaDesc) {
        metaDesc.setAttribute("content", "Format, minify, validate, and convert developer data structures instantly in your browser.");
      }
    }
  }, [currentRoute, tools]);

  const renderTool = () => {
    switch (currentRoute) {
      case "/code/formatters/json":
        return <JsonBeautifier isDarkMode={isDarkMode} />;
      case "/code/encoders-decoders/base64":
        return <Base64EncoderDecoder isDarkMode={isDarkMode} />;
      case "/code/encoders-decoders/url":
        return <UrlEncoderDecoder isDarkMode={isDarkMode} />;
      case "/code/encoders-decoders/jwt":
        return <JwtDecoder isDarkMode={isDarkMode} />;
      case "/code/hash-generators/md5":
      case "/code/hash-generators/sha1":
      case "/code/hash-generators/sha256":
      case "/code/hash-generators/sha512":
        return <HashGenerator isDarkMode={isDarkMode} currentRoute={currentRoute} />;
      case "/code/regex-tools/tester":
        return <RegexTester isDarkMode={isDarkMode} />;
      case "/generators/uuid-generator":
      case "/generators/password-generator":
        return <PasswordUuidGenerator isDarkMode={isDarkMode} currentRoute={currentRoute} />;
      case "/code/formatters/xml":
      case "/code/formatters/yaml":
      case "/code/formatters/toml":
      case "/code/formatters/sql":
      case "/code/formatters/html":
      case "/code/formatters/css":
      case "/code/formatters/javascript":
      case "/code/converters/json-yaml":
      case "/code/converters/json-toml": 
      case "/code/converters/json-csv":
      case "/code/converters/csv-tsv":
        return <FormattersConverters isDarkMode={isDarkMode} currentRoute={currentRoute} />;
      case "/developer/openapi-validator":
        return <OpenApiValidator isDarkMode={isDarkMode} />;
      case "/learning/markdown-editor":
        return <MarkdownEditor isDarkMode={isDarkMode} />;
      case "/developer/color-palette":
      case "/accessibility/color-contrast":
        return <ColorPaletteContrast isDarkMode={isDarkMode} />;
      case "/time-number/cron-generator-parser":
        return <CronParser isDarkMode={isDarkMode} />;
      case "/time-number/number-base-converter":
        return <NumberBaseConverter isDarkMode={isDarkMode} />;
      case "/student/complexity-analyzer":
        return <ComplexityAnalyzer isDarkMode={isDarkMode} />;
      default:
        return null;
    }
  };


  const isToolActive = (url) => {
    return currentRoute === url;
  };

  const hasActiveTool = renderTool() !== null;

  return (
    <div className={isDarkMode ? "bg-dark text-light" : "bg-light text-dark"} style={{ minHeight: "100vh" }}>
      <div className="d-flex border-top">
        {/* Sidebar */}
        <nav 
          className={`col-md-3 col-lg-2 d-md-block sidebar p-3 border-end ${isDarkMode ? "bg-dark text-light" : "bg-white text-dark"}`}
          style={{ 
            height: "calc(100vh - 62px)", 
            overflowY: "auto",
            position: "sticky",
            top: "62px"
          }}
        >
          <ul className="nav flex-column gap-1">
            <li className="nav-item mb-2">
              <a 
                href="/" 
                className={`nav-link d-flex align-items-center py-2 px-3 rounded-3 fw-semibold transition-all ${
                  currentRoute === "/" || !currentRoute
                    ? "bg-primary text-white shadow-sm"
                    : isDarkMode ? "text-light hover-bg-dark" : "text-dark hover-bg-light"
                }`}
                onClick={() => setSearch("")}
              >
                <i className="fas fa-th-large me-2"></i>
                Dashboard
              </a>
            </li>
            <hr className="my-2 opacity-25" />
            <span className="small text-muted text-uppercase tracking-wider px-3 mb-1 d-block fw-bold" style={{ fontSize: "10px" }}>
              Available Tools
            </span>
            {tools.map((tool, index) => (
              <li key={index} className="nav-item">
                <a 
                  href={tool.url} 
                  className={`nav-link d-flex align-items-center py-2 px-3 rounded-3 transition-all ${
                    isToolActive(tool.url)
                      ? "bg-primary text-white shadow-sm"
                      : isDarkMode ? "text-light-50 text-light opacity-75" : "text-dark opacity-75"
                  }`}
                  style={{ fontSize: "14px" }}
                >
                  <i className={`${tool.icon} me-2`} style={{ width: "16px", textAlign: "center" }}></i>
                  <span className="text-truncate">{tool.title}</span>
                </a>
              </li>
            ))}
          </ul>
        </nav>

        {/* Main Content Area */}
        <main 
          className="col-md-9 ms-sm-auto col-lg-10 px-md-4 overflow-auto"
          style={{ height: "calc(100vh - 62px)" }}
        >
          {hasActiveTool ? (
            renderTool()
          ) : (
            <div className="py-4">
              <div className="d-flex justify-content-between align-items-center mb-4 border-bottom pb-2">
                <h2 className="fw-bold m-0">Developer Utilities Directory</h2>
                <span className="badge bg-secondary px-3 py-2 rounded-pill">
                  {tools.filter(tool => tool.title.toLowerCase().includes(search.toLowerCase())).length} Tools Available
                </span>
              </div>
              <div className="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
                {tools.filter(tool => tool.title.toLowerCase().includes(search.toLowerCase())).map((tool, index) => (
                  <div key={index} className="col animate-hover-up">
                    <div 
                      className={`card h-100 shadow-sm text-center p-3 border-0 transition-all ${
                        isDarkMode ? "bg-dark text-white" : "bg-white text-dark"
                      }`} 
                      style={{
                        background: isDarkMode ? "rgba(33, 37, 41, 0.95)" : "rgba(255, 255, 255, 0.95)",
                        backdropFilter: "blur(10px)",
                        border: isDarkMode ? "1px solid rgba(255, 255, 255, 0.08)" : "1px solid rgba(0, 0, 0, 0.08)",
                        borderRadius: "16px"
                      }}
                    >
                      <div className="card-body d-flex flex-column align-items-center justify-content-between">
                        <div className="mb-3 p-3 rounded-circle" style={{
                          background: isDarkMode ? "rgba(255,255,255,0.05)" : "rgba(0,0,0,0.02)",
                          width: "70px",
                          height: "70px",
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "center"
                        }}>
                          <i className={`${tool.icon} fa-2x text-primary`}></i>
                        </div>
                        <h5 className="card-title fw-bold">{tool.title}</h5>
                        <p className="card-text text-muted small px-2 flex-grow-1">{tool.description}</p>
                        <a 
                          href={tool.url} 
                          className="btn btn-primary px-4 rounded-pill fw-semibold shadow-sm w-100 mt-3"
                        >
                          Use Tool
                        </a>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </main>
      </div>
      <footer className={`text-center py-3 border-top ${isDarkMode ? "bg-dark text-white-50 border-light-subtle" : "bg-white text-dark-50 border-dark-subtle"}`}>
          <p className="mb-0 small">© 2026 Dev Suite - powered by EC App Makers Studio</p>
      </footer>
    </div>
  );
;
}

